"""读取工作流 JSON 文件。"""

import json

from .errors import WorkflowDefinitionError, WorkflowInputError


def load_workflow_file(path: str):
    """读取并解析 JSON 文件。

    文件不可读抛 WorkflowInputError（INPUT_READ_ERROR）；
    JSON 非法抛 WorkflowDefinitionError（INVALID_JSON）。
    """
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = f.read()
    except OSError as exc:
        raise WorkflowInputError(f"无法读取文件 {path}: {exc}") from exc
    return parse_workflow_json(raw)


def parse_workflow_json(raw: str):
    """解析 JSON 字符串，非法时抛 INVALID_JSON。"""
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise WorkflowDefinitionError(
            "INVALID_JSON", f"JSON 解析失败（第 {exc.lineno} 行第 {exc.colno} 列）"
        ) from exc

"""工作流定义校验：结构、重试策略、依赖关系与参数。"""

import math
from typing import Any, Optional

from .errors import WorkflowDefinitionError
from .models import TaskDef

KNOWN_TASK_TYPES = ("value", "fail_now", "sleep")


def _err(code: str, message: str) -> WorkflowDefinitionError:
    return WorkflowDefinitionError(code, message)


def _is_real_number(value: Any) -> bool:
    # bool 是 int 的子类，需显式排除。
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def build_tasks(data: Any) -> tuple[list[TaskDef], Optional[int], Optional[float]]:
    """校验顶层工作流定义并返回 (有序 TaskDef 列表, max_concurrency, run_timeout)。

    max_concurrency 省略时为 None，表示不限制同时执行的任务数；
    run_timeout 省略时为 None，表示运行不限总时长。
    任何定义问题都抛 WorkflowDefinitionError，绝不产生其他异常类型。
    """
    if not isinstance(data, dict):
        raise _err("INVALID_SCHEMA", "工作流定义必须是 JSON 对象")

    name = data.get("name")
    if not isinstance(name, str) or not name:
        raise _err("INVALID_SCHEMA", "name 必须是非空字符串")

    tasks_raw = data.get("tasks")
    if not isinstance(tasks_raw, list):
        raise _err("INVALID_SCHEMA", "tasks 必须是数组")

    max_concurrency = _validate_concurrency_policy(data)
    run_timeout = _validate_run_timeout_policy(data)

    tasks: list[TaskDef] = []
    seen_ids: set[str] = set()

    for index, raw in enumerate(tasks_raw):
        if not isinstance(raw, dict):
            raise _err("INVALID_SCHEMA", f"第 {index} 个任务必须是 JSON 对象")

        task_id = raw.get("id")
        if not isinstance(task_id, str) or not task_id:
            raise _err("INVALID_SCHEMA", f"第 {index} 个任务的 id 必须是非空字符串")
        if task_id in seen_ids:
            raise _err("DUPLICATE_TASK_ID", f"任务 id 重复: {task_id}")
        seen_ids.add(task_id)

        task_type = raw.get("task_type")
        if not isinstance(task_type, str) or not task_type:
            raise _err("INVALID_SCHEMA", f"任务 {task_id} 的 task_type 必须是非空字符串")
        if task_type not in KNOWN_TASK_TYPES:
            raise _err(
                "INVALID_SCHEMA",
                f"任务 {task_id} 的 task_type 未知: {task_type}",
            )

        depends_on = _validate_depends_on(task_id, raw.get("depends_on", []))
        (
            max_attempts,
            retry_delay,
            backoff_multiplier,
            max_retry_delay,
        ) = _validate_retry_policy(task_id, raw)
        args = _validate_args_type(task_id, raw.get("args", {}))
        timeout_seconds = _validate_timeout_policy(task_id, raw)

        tasks.append(
            TaskDef(
                id=task_id,
                task_type=task_type,
                depends_on=tuple(depends_on),
                max_attempts=max_attempts,
                retry_delay_seconds=retry_delay,
                args=args,
                retry_backoff_multiplier=backoff_multiplier,
                max_retry_delay_seconds=max_retry_delay,
                timeout_seconds=timeout_seconds,
            )
        )

    _validate_dependency_references(tasks)
    _validate_no_cycle(tasks)
    _validate_task_args(tasks)

    return tasks, max_concurrency, run_timeout


def _validate_concurrency_policy(data: dict) -> Optional[int]:
    """max_concurrency 省略时为 None（不限并发）；否则必须是 >= 1 的整数。

    仅接受 JSON 整数：布尔值与 2.0 这类浮点一律拒绝。
    """
    if "max_concurrency" not in data:
        return None
    value = data["max_concurrency"]
    if not isinstance(value, int) or isinstance(value, bool):
        raise _err(
            "INVALID_CONCURRENCY_POLICY",
            "max_concurrency 必须是整数",
        )
    if value < 1:
        raise _err(
            "INVALID_CONCURRENCY_POLICY",
            "max_concurrency 不能小于 1",
        )
    return value


def _validate_run_timeout_policy(data: dict) -> Optional[float]:
    """顶层 timeout_seconds 省略时为 None（运行不限时）；否则必须是 >= 0 的有限数值。

    与任务级 timeout_seconds 同规则：布尔不算数值，NaN/inf 拒绝。
    """
    if "timeout_seconds" not in data:
        return None
    timeout = data["timeout_seconds"]
    if not _is_real_number(timeout) or not math.isfinite(timeout):
        raise _err(
            "INVALID_RUN_TIMEOUT_POLICY",
            "顶层 timeout_seconds 必须是有限数值",
        )
    if timeout < 0:
        raise _err(
            "INVALID_RUN_TIMEOUT_POLICY",
            "顶层 timeout_seconds 不能小于 0",
        )
    return float(timeout)


def _validate_depends_on(task_id: str, value: Any) -> list[str]:
    if not isinstance(value, list):
        raise _err("INVALID_SCHEMA", f"任务 {task_id} 的 depends_on 必须是数组")
    deps: list[str] = []
    for dep in value:
        if not isinstance(dep, str) or not dep:
            raise _err(
                "INVALID_SCHEMA",
                f"任务 {task_id} 的 depends_on 只能包含非空字符串",
            )
        if dep in deps:
            raise _err(
                "INVALID_SCHEMA",
                f"任务 {task_id} 的 depends_on 中依赖重复: {dep}",
            )
        deps.append(dep)
    return deps


def _validate_retry_policy(
    task_id: str, raw: dict
) -> tuple[int, float, float, Optional[float]]:
    max_attempts = raw.get("max_attempts", 1)
    # 仅接受整数次（1.0 这类浮点在 JSON 中若写为 1.0 也拒绝，避免歧义）。
    if not isinstance(max_attempts, int) or isinstance(max_attempts, bool):
        raise _err(
            "INVALID_RETRY_POLICY",
            f"任务 {task_id} 的 max_attempts 必须是整数",
        )
    if max_attempts < 1:
        raise _err(
            "INVALID_RETRY_POLICY",
            f"任务 {task_id} 的 max_attempts 不能小于 1",
        )

    retry_delay = raw.get("retry_delay_seconds", 0)
    if not _is_real_number(retry_delay) or not math.isfinite(retry_delay):
        raise _err(
            "INVALID_RETRY_POLICY",
            f"任务 {task_id} 的 retry_delay_seconds 必须是有限数值",
        )
    if retry_delay < 0:
        raise _err(
            "INVALID_RETRY_POLICY",
            f"任务 {task_id} 的 retry_delay_seconds 不能小于 0",
        )

    # 省略 multiplier 时默认 1（固定等待，与历史行为完全一致）。
    backoff_multiplier = raw.get("retry_backoff_multiplier", 1)
    if not _is_real_number(backoff_multiplier) or not math.isfinite(backoff_multiplier):
        raise _err(
            "INVALID_RETRY_POLICY",
            f"任务 {task_id} 的 retry_backoff_multiplier 必须是有限数值",
        )
    if backoff_multiplier < 1:
        raise _err(
            "INVALID_RETRY_POLICY",
            f"任务 {task_id} 的 retry_backoff_multiplier 不能小于 1",
        )

    # 省略上限时为 None，退避结果不截断。
    max_retry_delay: Optional[float] = None
    if "max_retry_delay_seconds" in raw:
        max_retry_delay = raw["max_retry_delay_seconds"]
        if not _is_real_number(max_retry_delay) or not math.isfinite(max_retry_delay):
            raise _err(
                "INVALID_RETRY_POLICY",
                f"任务 {task_id} 的 max_retry_delay_seconds 必须是有限数值",
            )
        if max_retry_delay < 0:
            raise _err(
                "INVALID_RETRY_POLICY",
                f"任务 {task_id} 的 max_retry_delay_seconds 不能小于 0",
            )
        max_retry_delay = float(max_retry_delay)

    return (
        max_attempts,
        float(retry_delay),
        float(backoff_multiplier),
        max_retry_delay,
    )


def _validate_args_type(task_id: str, value: Any) -> dict:
    if not isinstance(value, dict):
        raise _err("INVALID_ARGS", f"任务 {task_id} 的 args 必须是 JSON 对象")
    return value


def _validate_timeout_policy(task_id: str, raw: dict) -> Optional[float]:
    """timeout_seconds 省略时为 None（不限时）；否则必须是 >= 0 的有限数值。"""
    if "timeout_seconds" not in raw:
        return None
    timeout = raw["timeout_seconds"]
    if not _is_real_number(timeout) or not math.isfinite(timeout):
        raise _err(
            "INVALID_TIMEOUT_POLICY",
            f"任务 {task_id} 的 timeout_seconds 必须是有限数值",
        )
    if timeout < 0:
        raise _err(
            "INVALID_TIMEOUT_POLICY",
            f"任务 {task_id} 的 timeout_seconds 不能小于 0",
        )
    return float(timeout)


def _validate_dependency_references(tasks: list[TaskDef]) -> None:
    known = {task.id for task in tasks}
    for task in tasks:
        for dep in task.depends_on:
            if dep not in known:
                raise _err(
                    "UNKNOWN_DEPENDENCY",
                    f"任务 {task.id} 依赖了不存在的任务: {dep}",
                )


def _validate_no_cycle(tasks: list[TaskDef]) -> None:
    # Kahn 拓扑排序；处理完后仍有剩余节点即存在环（含自依赖）。
    graph = {task.id: set(task.depends_on) for task in tasks}
    processed: set[str] = set()
    while True:
        leaves = [tid for tid, deps in graph.items() if tid not in processed and not (deps - processed)]
        if not leaves:
            break
        processed.update(leaves)
    if len(processed) != len(graph):
        remaining = sorted(set(graph) - processed)
        raise _err(
            "DEPENDENCY_CYCLE",
            f"依赖关系中存在环，涉及任务: {', '.join(remaining)}",
        )


def _validate_task_args(tasks: list[TaskDef]) -> None:
    by_id = {task.id: task for task in tasks}
    for task in tasks:
        if task.task_type == "value":
            has_value = "value" in task.args
            has_ref = "ref" in task.args
            if not has_value and not has_ref:
                raise _err(
                    "INVALID_ARGS",
                    f"任务 {task.id} 的 value 类型要求 args.value 或 args.ref",
                )
            if has_ref:
                ref = task.args["ref"]
                if not isinstance(ref, str) or not ref:
                    raise _err(
                        "INVALID_ARGS",
                        f"任务 {task.id} 的 args.ref 必须是非空字符串",
                    )
                if ref not in task.depends_on:
                    raise _err(
                        "INVALID_ARGS",
                        f"任务 {task.id} 的 ref 目标 {ref} 必须出现在 depends_on 中",
                    )
        # fail_now 对 args 无额外要求。
        if task.task_type == "sleep":
            if "seconds" not in task.args or "output" not in task.args:
                raise _err(
                    "INVALID_ARGS",
                    f"任务 {task.id} 的 sleep 类型要求同时提供 args.seconds 与 args.output",
                )
            seconds = task.args["seconds"]
            if not _is_real_number(seconds) or not math.isfinite(seconds):
                raise _err(
                    "INVALID_ARGS",
                    f"任务 {task.id} 的 args.seconds 必须是有限数值",
                )
            if seconds < 0:
                raise _err(
                    "INVALID_ARGS",
                    f"任务 {task.id} 的 args.seconds 不能小于 0",
                )

"""命令行入口：python -m floworch <workflow.json>

退出码：0 成功；1 工作流执行失败（结果仍打印）；2 定义或输入错误。
"""

import argparse
import json
import sys
from dataclasses import asdict
from typing import Optional

from .engine import run_workflow
from .errors import WorkflowDefinitionError, WorkflowInputError
from .loader import load_workflow_file


def _task_result_to_dict(result) -> dict:
    return {
        "status": result.status,
        "attempts": result.attempts,
        "output": result.output,
        "error": result.error,
    }


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        prog="python -m floworch",
        description="执行 JSON 定义的 DAG 工作流",
    )
    parser.add_argument("workflow_file", help="工作流 JSON 文件路径")
    args = parser.parse_args(argv)

    try:
        workflow = load_workflow_file(args.workflow_file)
        run_result = run_workflow(workflow)
    except (WorkflowInputError, WorkflowDefinitionError) as exc:
        print(
            json.dumps({"error": {"code": exc.code, "message": exc.message}}, ensure_ascii=False),
            file=sys.stderr,
        )
        return 2

    payload = {
        "run_id": run_result.run_id,
        "status": run_result.status,
        "results": {
            task_id: _task_result_to_dict(result)
            for task_id, result in run_result.results.items()
        },
    }
    print(json.dumps(payload, ensure_ascii=False, indent=2))
    return 1 if run_result.status == "failed" else 0


if __name__ == "__main__":
    sys.exit(main())

"""DAG 调度引擎：并发执行、并发上限、失败重试、单次尝试超时、工作流总时限与下游跳过。"""

import threading
import time
from concurrent.futures import ThreadPoolExecutor, wait
from datetime import datetime, timezone
from typing import Any, Optional

from .errors import TaskExecutionError
from .models import CallbackEvent, EventCallback, RunResult, TaskDef, TaskResult
from .tasks import run_once
from .validator import build_tasks

# 工作流总时限到期后，未进入终态的任务统一使用的错误码。
WORKFLOW_TIMEOUT_CODE = "WORKFLOW_TIMEOUT"


class _AttemptTimeout(Exception):
    """单次尝试超过 timeout_seconds；结果 error.code 固定为 TASK_TIMEOUT。"""

    code = "TASK_TIMEOUT"

    def __init__(self, task_id: str, attempt: int, timeout_seconds: float):
        self.message = (
            f"任务 {task_id} 第 {attempt} 次尝试超过 {timeout_seconds} 秒未完成"
        )
        super().__init__(self.message)


class _RunTimedOut(Exception):
    """工作流总时限到期：当前尝试或重试等待立即中止。"""


def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def _retry_wait_seconds(task: TaskDef, attempt: int) -> float:
    """第 attempt 次失败后、准备第 attempt+1 次尝试前的实际等待秒数。

    基础 delay 乘以 multiplier 的 attempt-1 次方；配置上限后取计算值
    与上限的较小值。delay 为 0 时结果恒为 0（multiplier 已由校验
    保证为有限值，不会产生 NaN/inf）。
    """
    delay = task.retry_delay_seconds * (
        task.retry_backoff_multiplier ** (attempt - 1)
    )
    if task.max_retry_delay_seconds is not None:
        delay = min(delay, task.max_retry_delay_seconds)
    return delay


def _run_attempt(
    task: TaskDef,
    results: dict[str, TaskResult],
    attempt: int,
    deadline: Optional[float],
) -> Any:
    """执行一次任务体，成功返回输出。

    失败抛 TaskExecutionError；超过任务级 timeout_seconds 抛 _AttemptTimeout；
    到达工作流总时限截止抛 _RunTimedOut。未配置任何超时时保持同步直调；
    任务级 timeout_seconds 为 0 时不执行任务体，立即判超时。超时或总时限
    到期后任务体线程被遗弃（守护线程，不阻塞进程退出），其晚到的结果不会
    被采纳，因此不可能误报成功。
    """
    timeout = task.timeout_seconds

    if deadline is not None and time.monotonic() >= deadline:
        raise _RunTimedOut
    if timeout is not None and timeout <= 0:
        raise _AttemptTimeout(task.id, attempt, timeout)

    # 既未配置任务级超时也未配置总时限：同步直调，保持原有调用路径。
    if timeout is None and deadline is None:
        return run_once(task, results)

    # 每次尝试单独持有取消事件：到任一截止未完成都会 set 它，
    # 使可中断的 sleep 立即结束；不复用，避免污染后续重试。
    cancel = threading.Event()
    holder: dict[str, Any] = {}

    def worker() -> None:
        try:
            holder["output"] = run_once(task, results, cancel)
        except BaseException as exc:  # noqa: BLE001 - 交回主线程按原语义抛出
            holder["exc"] = exc

    runner = threading.Thread(
        target=worker, name=f"attempt-{task.id}-{attempt}", daemon=True
    )
    runner.start()
    if timeout is not None and deadline is not None:
        # 两个截止同时存在时取较早者，保证 sleep 在总时限点也能立即结束。
        join_seconds: Optional[float] = min(
            timeout, max(0.0, deadline - time.monotonic())
        )
    elif timeout is not None:
        join_seconds = timeout
    else:
        join_seconds = max(0.0, deadline - time.monotonic())
    runner.join(join_seconds)
    # 先判总时限：join 等到截止点即到期，与任务体线程是否恰在此微窗口内
    # 结束无关——其晚到结果一律不采纳（与任务级超时的遗弃策略一致）。
    if deadline is not None and time.monotonic() >= deadline:
        cancel.set()
        raise _RunTimedOut
    if runner.is_alive():
        # 任务级超时到截止仍未完成：中止可中断等待（sleep），不再 join。
        cancel.set()
        raise _AttemptTimeout(task.id, attempt, timeout)
    if "exc" in holder:
        raise holder["exc"]
    return holder["output"]


def run_workflow(workflow: dict, callback: Optional[EventCallback] = None) -> RunResult:
    """校验并执行一个工作流定义。

    workflow 为已解析的 JSON 对象，含 name、tasks，可选 max_concurrency 与
    顶层 timeout_seconds。定义无效抛 WorkflowDefinitionError；返回 RunResult
    汇总每个任务的结果。相互独立的任务在线程池中并发执行；配置
    max_concurrency 时，同时占用额度的任务不超过该值——额度自 task_started
    起占用，重试等待期间不释放，直到 task_succeeded、task_failed 或
    task_skipped 才释放。

    配置顶层 timeout_seconds 后，从校验完成、执行开始时起算总时限：到期不再
    启动新任务、新尝试或重试等待，正在等待的 sleep 立即结束；已成功任务保留
    原输出，其余未进入终态的任务统一记 failed（error.code 为 WORKFLOW_TIMEOUT，
    attempts 为已经实际开始的尝试次数），整体 status 为 failed。
    """
    tasks, max_concurrency, run_timeout = build_tasks(workflow)
    name = workflow["name"]

    # 总时限从校验完成、执行开始时起算；省略时 deadline 为 None（不限时）。
    deadline: Optional[float] = (
        None if run_timeout is None else time.monotonic() + run_timeout
    )

    # 结果按定义顺序输出；先建好账本，任务完成后按 id 回填。
    results: dict[str, TaskResult] = {}
    remaining_deps = {task.id: len(task.depends_on) for task in tasks}
    dependents: dict[str, list[str]] = {task.id: [] for task in tasks}
    for task in tasks:
        for dep in task.depends_on:
            dependents[dep].append(task.id)

    by_id = {task.id: task for task in tasks}
    # 保护回调串行可见性、results 回填、到期状态与调度账本。
    state_lock = threading.Lock()
    # 总时限到期事件：set 后唤醒重试等待，并让调度循环立即收口。
    timed_out = threading.Event()
    timeout_announced = False

    def emit(
        event: str, task_id: str, attempt: int, wait_seconds: Optional[float] = None
    ) -> None:
        if callback is not None:
            callback(
                CallbackEvent(event, task_id, attempt, _utc_now_iso(), wait_seconds)
            )

    def announce_timeout() -> None:
        """宣布总时限到期（run_timed_out 只发一次）。调用方须持有 state_lock。"""
        nonlocal timeout_announced
        if not timeout_announced:
            timeout_announced = True
            timed_out.set()
            emit("run_timed_out", "", 0, None)

    def timeout_error() -> dict[str, Any]:
        return {
            "code": WORKFLOW_TIMEOUT_CODE,
            "message": f"工作流运行超过总时限 {run_timeout} 秒",
        }

    # timeout_seconds 为 0（理论上 deadline 已过同样如此）：不执行任何
    # 任务体，所有任务 attempts 为 0、得到同一个 WORKFLOW_TIMEOUT 错误。
    if deadline is not None and time.monotonic() >= deadline:
        with state_lock:
            announce_timeout()
        shared_error = timeout_error()
        ordered = {
            task.id: TaskResult(
                status="failed", attempts=0, output=None, error=dict(shared_error)
            )
            for task in tasks
        }
        return RunResult(run_id=name, status="failed", results=ordered)

    def execute_task(task: TaskDef) -> TaskResult:
        """在工作线程中执行单个任务，含重试循环。"""

        def fail_by_timeout(attempts: int) -> TaskResult:
            with state_lock:
                announce_timeout()
            return TaskResult(
                status="failed",
                attempts=attempts,
                output=None,
                error=timeout_error(),
            )

        for attempt in range(1, task.max_attempts + 1):
            # 到期后不再启动新尝试：attempts 只计已经实际开始的次数。
            # 锁内同时看宣布事件与原始时钟，跨过截止点就由本线程原子宣布，
            # 避免 deadline 已过、主循环尚未唤醒时多发出一次 task_started。
            with state_lock:
                expired = timed_out.is_set() or (
                    deadline is not None and time.monotonic() >= deadline
                )
                if expired:
                    announce_timeout()
                    return TaskResult(
                        status="failed",
                        attempts=attempt - 1,
                        output=None,
                        error=timeout_error(),
                    )
                emit("task_started", task.id, attempt)
            try:
                output = _run_attempt(task, results, attempt, deadline)
            except _RunTimedOut:
                return fail_by_timeout(attempt)
            except (TaskExecutionError, _AttemptTimeout) as exc:
                if attempt < task.max_attempts:
                    # 等待发生在 task_retrying 之后、下一次 task_started 之前。
                    wait_seconds = _retry_wait_seconds(task, attempt)
                    with state_lock:
                        emit("task_retrying", task.id, attempt, wait_seconds)
                    if wait_seconds > 0:
                        # 总时限到期立即结束重试等待（未配置总时限时
                        # timed_out 永不 set，等价于原来的 time.sleep）。
                        timed_out.wait(wait_seconds)
                    # 等待结束（含 0 秒等待）：锁内按事件与时钟裁定，
                    # 跨过截止点就由本线程原子宣布，不再进入下一次尝试。
                    with state_lock:
                        expired = timed_out.is_set() or (
                            deadline is not None and time.monotonic() >= deadline
                        )
                        if expired:
                            announce_timeout()
                            return TaskResult(
                                status="failed",
                                attempts=attempt,
                                output=None,
                                error=timeout_error(),
                            )
                    continue
                with state_lock:
                    emit("task_failed", task.id, attempt)
                return TaskResult(
                    status="failed",
                    attempts=attempt,
                    output=None,
                    error={"code": exc.code, "message": exc.message},
                )
            else:
                with state_lock:
                    emit("task_succeeded", task.id, attempt)
                return TaskResult(status="success", attempts=attempt, output=output)
        # 理论上不可达（max_attempts >= 1 已由校验保证）。
        raise RuntimeError(f"任务 {task.id} 的重试循环异常退出")

    def skip_task(task: TaskDef) -> TaskResult:
        with state_lock:
            emit("task_skipped", task.id, 0)
        return TaskResult(status="skipped", attempts=0, output=None, error=None)

    ready = [task.id for task in tasks if not task.depends_on]
    max_workers = max(1, len(tasks))
    with ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures: dict[Any, str] = {}

        def release_children(tid: str) -> None:
            for child in dependents[tid]:
                remaining_deps[child] -= 1
                if remaining_deps[child] == 0:
                    ready.append(child)

        def submit(tid: str) -> None:
            task = by_id[tid]
            deps_succeeded = all(
                results[dep].status == "success" for dep in task.depends_on
            )
            if deps_succeeded:
                futures[pool.submit(execute_task, task)] = tid
            else:
                # 依赖中有 failed/skipped：本任务及（稍后）其下游一律跳过。
                results[tid] = skip_task(task)
                release_children(tid)

        while True:
            with state_lock:
                if deadline is not None and time.monotonic() >= deadline:
                    announce_timeout()

            # 到期后不再启动新任务：就绪队列不再提交，只等在途任务收口。
            if not timed_out.is_set():
                # 并发额度由在途 future 数体现：任务自提交（task_started）起
                # 占用一份额度，重试等待也在其 future 内，直到终态事件后
                # future 完成才释放。skipped 任务不进线程池，不占额度。
                while ready and (
                    max_concurrency is None or len(futures) < max_concurrency
                ):
                    submit(ready.pop())

            # 跳过的任务可能在不经过线程池的情况下连锁放行下游。
            if not futures:
                break

            if deadline is not None and not timed_out.is_set():
                wait_timeout = max(0.0, deadline - time.monotonic())
            else:
                # 已到期：在途尝试自带截止、重试等待已被唤醒，很快都会结束。
                wait_timeout = None

            done, _ = wait(
                set(futures),
                timeout=wait_timeout,
                return_when="FIRST_COMPLETED",
            )
            if not done:
                # 等待达到总时限截止仍无任务完成：宣布到期后收一轮在途任务。
                with state_lock:
                    if deadline is not None and time.monotonic() >= deadline:
                        announce_timeout()
                continue
            for future in done:
                tid = futures.pop(future)
                results[tid] = future.result()
                release_children(tid)

    # 到期收口：未进入终态的任务（未提交或未回填）统一记 WORKFLOW_TIMEOUT，
    # attempts 为 0；此前已 success/failed/skipped 的结果原样保留。
    if timed_out.is_set():
        shared_error = timeout_error()
        for task in tasks:
            if task.id not in results:
                results[task.id] = TaskResult(
                    status="failed",
                    attempts=0,
                    output=None,
                    error=dict(shared_error),
                )
        overall_failed = True
    else:
        overall_failed = any(
            results[task.id].status == "failed" for task in tasks
        )

    ordered = {task.id: results[task.id] for task in tasks}
    return RunResult(
        run_id=name,
        status="failed" if overall_failed else "success",
        results=ordered,
    )

